<script setup lang="ts">
import {t as tr} from "../../i18n";
import {computed,ref} from 'vue';import {useBusinessStore,businessApi} from '../../stores/business';import type {ScheduledRulePlan} from '@shared/business';
import {recipientsText,effectsText,statusMeta,humanizeIsoText} from '../../business/automation-format';
const props=defineProps<{plan:ScheduledRulePlan;scopeKey:string;readonly?:boolean}>(),business=useBusinessStore(),busy=ref(false),confirmed=ref(''),confirmedDetail=ref(''),error=ref('');
const ACTION_TEXT:Record<string,string>={create:'新建规则',update:'修改规则',delete:'删除规则',pause:'暂停规则',resume:'恢复规则',replace:'替换规则'};
const actionText=computed(()=>ACTION_TEXT[props.plan.action]||props.plan.action);
const recipientsLabel=computed(()=>recipientsText(props.plan.spec.recipients as Array<Record<string,string>>));
async function confirm(){if(props.readonly||props.scopeKey!==business.scopeKey)return;busy.value=true;error.value='';try{const r=await businessApi<{job:{id:string;status:string;version:number}}>('proxy/scheduled-jobs/confirm',{scopeKey:props.scopeKey,planId:props.plan.id});confirmed.value=statusMeta(r.job.status).label;confirmedDetail.value=tr('规则编号')+' '+r.job.id+' · '+tr('版本')+' v'+r.job.version;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section :aria-label="tr('定时规则待确认方案')"><b>{{plan.spec.name}} · {{actionText}}</b><button v-if="!confirmed" :disabled="busy||readonly||business.scopeKey!==scopeKey" @click="confirm">{{tr("本人核对后确认此规则操作")}}</button><p v-else>{{tr("已确认规则：")}}{{confirmed}}{{tr("。结果与审计可从「定时任务与提醒」回查。")}}</p><p>{{tr("时区")}} {{plan.spec.timezone}} {{tr("· 接收对象")}} {{recipientsLabel}} {{tr("· 效果")}} {{effectsText(plan.spec.approvedEffects)}}</p><ol><li v-for="o in plan.futureOccurrences" :key="o.at">{{humanizeIsoText(o.local)}}</li></ol><details><summary>{{tr("到点内容样例")}}</summary><pre>{{humanizeIsoText(plan.sample.text)}}</pre></details><details v-if="confirmedDetail" class="card__more"><summary>{{tr("说明")}}</summary><p>{{confirmedDetail}}</p></details><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}section{padding:10px;border:1px solid var(--border);border-radius:8px}</style>